addBuff.text:
addBuff(def: BuffEffect, durationScale = 1, chainDepth = 0, tags?: SkillTag[]): void {
    // Every application — fresh, stacking, or refresh — counts as GAINING
    // the buff (the buffGain trigger's event).
    if (this.gainEvents.length < 64) {
      this.gainEvents.push({ kind: 'buff', id: def.id, depth: chainDepth, buff: def, tags });
    }
    const existing = this.buffs.get(def.id);
    const duration = def.duration * durationScale;
    const grant = def.stacksOnApply ?? 1;
    // INDEPENDENT stack clocks (Deep Carve): each application ADDS a stack
    // on its own timer — nothing refreshes; old cuts close as new ones open.
    if (def.stackTimers === 'independent' && (def.maxStacks ?? 1) > 1) {
      const buff = existing ?? { def, remaining: 0, stacks: 0, expiries: [] as number[] };
      buff.expiries ??= [];
      for (let i = 0; i < grant && buff.expiries.length < (def.maxStacks ?? 1); i++) {
        buff.expiries.push(duration);
      }
      buff.stacks = buff.expiries.length;
      buff.remaining = Math.max(...buff.expiries);
      this.buffs.set(def.id, buff);
      this.syncBuffSource(def.id);
      return;
    }
    if (existing && (def.maxStacks ?? 1) > 1) {
      existing.stacks = Math.min(def.maxStacks ?? 1, existing.stacks + grant);
      existing.remaining = duration;
      existing.def = def; // dynamic-value buffs re-price on refresh
      this.buffs.set(def.id, existing);
    } else if (existing) {
      existing.remaining = duration;
      // DYNAMIC-VALUE refresh (Echoing Might): the newest application's
      // def replaces the old, so computed mod values re-price each grant.
      existing.def = def;
      this.buffs.set(def.id, existing);
    } else {
      this.buffs.set(def.id, {
        def, remaining: duration,
        stacks: Math.min(def.maxStacks ?? grant, grant),
      });
    }
    this.syncBuffSource(def.id);
  }

consumeBuffStacks.text:
consumeBuffStacks(id: string, n = 1): void {
    const buff = this.buffs.get(id);
    if (!buff) return;
    noteProcCue(this, buffProcCue(buff.def), 'release', id, Math.min(n, buff.stacks));
    buff.stacks -= n;
    if (buff.stacks <= 0) this.buffs.delete(id);
    this.syncBuffSource(id);
  }

spendBuffs.text:
spendBuffs(on: NonNullable<BuffEffect['consumeOn']>['on'], tags?: readonly SkillTag[], skillId?: string): void {
    if (!this.buffs.size) return;
    for (const [id, buff] of [...this.buffs]) {
      const def = buff.def;
      const c = def.consumeOn ?? (def.consumeOnUse ? { on: 'use' as const, tags: def.consumeOnUse.tags } : undefined);
      if (!c || c.on !== on) continue;
      if (c.tags && !c.tags.some(t => tags?.includes(t))) continue;
      if (c.skills && (!skillId || !c.skills.includes(skillId))) continue;
      this.consumeBuffStacks(id, 1);
    }
  }

syncBuffSource.text:
private syncBuffSource(id: string): void {
    const buff = this.buffs.get(id);
    if (!buff) { this.sheet.removeSource('buff:' + id); return; }
    const mods: Modifier[] = buff.def.mods.map(m => ({ ...m, value: m.value * buff.stacks }));
    this.sheet.setSource('buff:' + id, mods);
  }

timerLoop.text:
for (const [id, buff] of this.buffs) {
      // Independent stack clocks: cull each expiry on its own, re-sync
      // when the count moves; the buff ends when the last stack closes.
      if (buff.expiries) {
        let moved = false;
        for (let i = buff.expiries.length - 1; i >= 0; i--) {
          buff.expiries[i] -= dt;
          if (buff.expiries[i] <= 0) { buff.expiries.splice(i, 1); moved = true; }
        }
        if (buff.expiries.length === 0) {
          this.buffs.delete(id);
          this.syncBuffSource(id);
        } else if (moved) {
          buff.stacks = buff.expiries.length;
          buff.remaining = Math.max(...buff.expiries);
          this.syncBuffSource(id);
        } else {
          buff.remaining -= dt;
        }
        continue;
      }
      buff.remaining -= dt;
      if (buff.remaining <= 0) {
        this.buffs.delete(id);
        this.syncBuffSource(id);
      }
    }

activeBuff.text:
export interface ActiveBuff {
  def: BuffEffect;
  remaining: number;
  stacks: number;
  /** INDEPENDENT stack clocks (BuffEffect.stackTimers 'independent'):
   *  one expiry per stack; stacks = expiries.length. `remaining` mirrors
   *  the LONGEST-lived stack for display. */
  expiries?: number[];
}

buffEffect.text:
export interface BuffEffect {
  /** Stored payload body/HUD material. Consumable buffs inherit a profile;
   * other buffs opt in. False hides only this supplementary presentation. */
  storedCue?: import('../data/procCues').ProcCueSpec | false;
  /** Player-facing name for dynamically scoped buffs such as companion bonds. */
  label?: string;
  type: 'buff';
  id: string;             // buffs with the same id refresh instead of stacking...
  duration: number;
  mods: Modifier[];
  maxStacks?: number;     // ...unless maxStacks > 1
  /** Stack CLOCKS: 'shared' (default) — any application refreshes the
   *  WHOLE pile's timer (Carve: keep swinging or lose it all at once);
   *  'independent' — every stack lives and dies on its OWN clock (Deep
   *  Carve: no refreshes, only additions; old cuts close as new ones open). */
  stackTimers?: 'shared' | 'independent';
  /** Grant this many stacks per application instead of one (clamped to
   *  maxStacks) — how an imbuement loads its whole magazine in one press. */
  stacksOnApply?: number;
  /** THE GAUGE's stack lane (engine/gauge.ts): stacks granted PER UNIT of
   *  the pressing use's gauge POWER (rounded, at least 1 while any power
   *  stands; clamped to maxStacks) — a half-full press wears half the
   *  stacks, an overflow press more than the full. A gauge-less skill
   *  reads power 1 (exactly `powerStacks`). Outranks stacksOnApply. */
  powerStacks?: number;
  /** Recipient: default 'caster'; 'minions' = every living minion of the
   *  caster (the generic minion-war-cry seam — Convocation's mend). */
  affects?: 'caster' | 'minions' | 'allies';
  /** Nearby allies include the caster; same team and story, no constructs. */
  radius?: number;
  /** ALL stacks are stripped when the bearer takes a LANDED hit (DoT ticks
   *  never wipe) — Tempo-style fragility as a buff's cost. */
  clearOnHit?: true;
  /** AMMUNITION (imbuements): each completed REAL use of a skill matching
   *  ANY of these tags (omit = every skill) spends one stack; at zero the
   *  buff ends. Give the buff tag-filtered mods over the same tags and you
   *  have "the next X uses are imbued". NOTE: the granting skill's own tags
   *  must NOT match, or the grant press eats its first round. */
  consumeOnUse?: { tags?: SkillTag[] };
  /** THE CONSUMABLE BUFF (the talent fabric, docs/engine/talents.md —
   *  consumeOnUse generalized to every event the ledger stamps): each
   *  matching event spends one stack, and the last stack ends the buff.
   *  'use' = a completed real use (consumeOnUse's exact law); 'hit' /
   *  'crit' / 'kill' = the bearer LANDS one; 'hurt' = the bearer TAKES a
   *  landed hit; 'block' / 'evade' = the bearer makes one. `tags` gates on
   *  the skill involved (ANY-match, like consumeOnUse); `skills` on its id.
   *  Give the buff mods scoped to the same tags and you have "your next
   *  two melee hits deal 50% more", "the next spell you cast is free", or
   *  "after being struck, your next attack strikes twice" — each one buff.
   *  The event spends AFTER the hit it empowered has resolved, so the
   *  buff's own mods always reach the blow that consumes it. */
  consumeOn?: {
    on: 'use' | 'hit' | 'crit' | 'kill' | 'hurt' | 'block' | 'evade';
    tags?: SkillTag[];
    skills?: string[];
  };
  /** NEXT-HIT RIDER: the bearer's next landed hit(s) carry a payload —
   *  one stack spent per landed hit. Because buffs land on ALLIES and
   *  MINIONS too (affects: 'minions' / targeted deliveries), "bless the
   *  Amalgam so its next blow poisons hugely" is one buff. */
  nextHit?: NextHitRider;
  /** POWER-SCALED: every mod value multiplies by the use's power mult —
   *  a brim release at 40% fill grants 40%-strength blessing (Surgewind's
   *  gathered stride). Opt-in so ordinary buffs never wobble with damage
   *  multipliers. */
  powerScaled?: true;
  /** LIFE BOND (the Chloromancer shape): applying this buff to an ALLY
   *  bonds the CASTER to them — a share of the caster's damage dealt
   *  (their bondShare stat × the striking skill's bondFeed) flows to the
   *  bonded as healing while the buff holds. One bond per caster. */
  bond?: true;
}
